"""Portfolio-specific editorial composition; facts remain in build-portfolio.py."""
import re

def branding(books,scope,arrow):
 selectors=''.join(f'<a href="#{b["id"]}" id="select-{b["id"]}" data-project="{b["id"]}"><strong>{b["name"]}</strong><span>{b["type"]}</span>{arrow}</a>' for b in books)
 panels=''.join(f'''<div class="book-panel" id="{b['id']}" data-book-panel data-cover="/assets/{b['img']}" data-movie="/assets/{b['video']}"><h3 id="{b['id']}-title">{b['name']}</h3><p class="project-discipline">{b['type']}</p><p>{b['description']}</p><details class="scope-details"><summary>O que desenvolvi <span class="icon i-plus" aria-hidden="true"></span></summary>{scope(b['items'])}</details>{'<small>'+b['credit']+'</small>' if b.get('credit') else ''}<noscript><a class="text-link" href="/assets/{b['video']}">Ver a entrega {arrow}</a></noscript></div>''' for b in books)
 first=books[0]
 preview=f'''<div class="portfolio-book-preview" data-preview><div class="notebook"><img class="notebook-shell" src="/assets/portfolio-notebook-frame-optimized.webp" width="1280" height="770" alt="" loading="lazy"><div class="notebook-screen"><img src="/assets/{first['img']}" width="1200" height="675" alt="Book de {first['name']}." loading="lazy"><video muted loop playsinline preload="none" data-src="/assets/{first['video']}" aria-label="Prévia do projeto de {first['name']}" hidden></video></div></div><div class="portfolio-book-actions"><a class="text-link" href="/assets/{first['video']}" data-zoom data-video data-alt="Book de {first['name']}">Ampliar a entrega {arrow}</a><button type="button" class="text-link preview-pause" aria-pressed="false" hidden>Pausar prévia</button></div></div>'''
 return f'''<section class="portfolio-branding section" id="estrategias" aria-labelledby="branding-title"><div class="wrap"><div class="portfolio-section-heading"><h2 id="branding-title">Estratégias de marca.<br><em>Decisões que ganham forma.</em></h2><p>Explore os três projetos. Cada seleção apresenta o book e o escopo desenvolvido.</p></div><nav class="book-switcher" aria-label="Escolher uma estratégia de marca">{selectors}</nav><div class="branding-workspace">{preview}<div class="branding-panels">{panels}</div></div></div></section>'''

def case_body(c,scope,img,film,campaignfilm):
 participation='<section class="case-participation" aria-labelledby="participation-title"><h2 id="participation-title">Minha <em>participação.</em></h2>'+scope(c['roles'])+'</section>'
 result=f'<section class="case-results" aria-labelledby="results-title"><h2 id="results-title">Resultados <em>e registros.</em></h2><p>{c["result"]}</p>'
 if c['id']=='bahari':
  # The campaign film supports the contribution list; no mixed-purpose gallery.
  first='<div class="case-work-chapter">'+participation+'<div class="case-film-column"><h3>A campanha em vídeo</h3>'+film()+'</div></div>'
  proofs=img('portfolio-bahari-feed.webp','Feed da Bahari com publicação de 1,1 milhão de visualizações.','Uma publicação com 1,1 milhão de visualizações, no feed da marca.')+img('bahari-proof.webp','Quatro publicações da Bahari: 411 mil, 350 mil, 287 mil e 249 mil visualizações.','Outros conteúdos da campanha. Amostra dos resultados documentados.')
  stories=img('bahari-story-v9.webp','Conteúdo comercial da Bahari destacando seus produtos.','Apresentação dos produtos e de seus diferenciais.')+img('portfolio-bahari-story.webp','Story interativo da Bahari sobre sustentação dos produtos.','Interação com o público sobre os diferenciais das peças.')
  production=img('portfolio-bahari-production.webp','Cronograma de maquiagem e shooting do photoshoot de São Paulo.','Organização de casting, equipe de beleza e cronograma de gravações.')
  return first+result+'<div class="case-proof-pair">'+proofs+'</div></section><section class="case-chapter" aria-labelledby="production-title"><h2 id="production-title">Comunicação <em>e bastidores.</em></h2><div class="case-production-layout"><div><h3>Conteúdo e interação</h3><div class="case-story-pair">'+stories+'</div></div><div><h3>Planejamento de produção</h3>'+production+'</div></div></section>'
 if c['id']=='julia-nunes':
  films=campaignfilm('esporte','Propostas para o esporte','Roteirização, apoio à captação e edição de conteúdo audiovisual.')+campaignfilm('mulher','Mulher na política','Roteirização, apoio à captação e edição de vídeo.')
  proofs=img('julia-nunes-results-v9.webp','Instagram Insights: 340.201 visualizações e 203.858 visualizadores.','Publicação colaborativa com mais de 340 mil visualizações.')+img('portfolio-julia-reel.webp','Reel com 283.747 visualizações e 5.681 interações.','Desempenho de um conteúdo audiovisual da campanha.')+img('portfolio-julia-followers.webp','Instagram Insights: 87.650 seguidores e crescimento de 7,5% em 30 dias.','Audiência em um recorte de 30 dias; período diferente do total da campanha.')
  return participation+'<section class="case-chapter" aria-labelledby="audiovisual-title"><h2 id="audiovisual-title">Da estratégia <em>aos conteúdos.</em></h2><div class="case-film-pair">'+films+'</div></section>'+result+'<div class="case-insight-trio">'+proofs+'</div></section>'
 if c['id']=='sepulveda':
  products=img('portfolio-sepulveda-trufa.webp','Trufa de chocolate da Sepulveda Chocolates.','Produtos da Sepulveda Chocolates. Imagem fornecida para o portfólio.')+img('portfolio-sepulveda-chocolate.webp','Chocolate artesanal da Sepulveda com fatias de laranja.','Detalhe dos produtos da marca. Imagem fornecida para o portfólio.')
  return participation+'<section class="case-chapter" aria-labelledby="products-title"><h2 id="products-title">O produto no centro<br><em>da comunicação.</em></h2><div class="case-product-pair">'+products+'</div></section>'+result+'<div class="case-report-layout"><div><h3>Da comunicação ao resultado comercial.</h3><p>O relato da cliente registra o faturamento da campanha e a percepção de conversão e recompra. Os valores são apresentados conforme esse relato.</p><dl class="case-revenue"><div><dt>Páscoa anterior</dt><dd>R$ 10 mil</dd></div><div><dt>Páscoa 2024</dt><dd>R$ 30 mil</dd></div></dl></div>'+img('sepulveda-proof.webp','Relato da cliente sobre faturamento, conversão e recompra.','Relato original da cliente sobre a campanha de Páscoa 2024.')+'</div></section>'
 if c['id']=='bruna':
  portrait=img('bruna-cover-v10.webp','Imagem de apresentação de Bruna Mariana, fornecida para o projeto.','Apresentação da profissional no perfil @psi.brunamariana.')
  feed=img('portfolio-bruna-feed.webp','Feed de Bruna Mariana com exemplos de publicações sobre relações e saúde emocional.','Seleção de conteúdos do perfil. A produção textual é realizada pela cliente.')
  proofs=img('portfolio-bruna-proof-1.webp','Resultados da publicação Vínculo seguro, com os indicadores originais.','Publicação sobre vínculos: captura original de desempenho.')+img('portfolio-bruna-proof-2.webp','Resultados de outra publicação de Bruna Mariana, registrada em 5 de novembro.','Outra publicação do perfil: indicadores do Instagram.')+img('portfolio-bruna-proof-3.webp','Resultados de publicação sobre instabilidade emocional no ambiente familiar.','Conteúdo sobre relações familiares: captura original de desempenho.')+img('bruna-result-v9.webp','Publicação Crescer sem ser visto ou ouvido não passa em branco, com 3,4 mil curtidas e 1 mil salvamentos.','Publicação citada nos destaques: 3,4 mil curtidas, 758 compartilhamentos e 1 mil salvamentos.')
  bruna_result='<section class="case-results" aria-labelledby="results-title"><h2 id="results-title">Resultados <em>e registros.</em></h2><p>Amostra de publicações do perfil. Os indicadores abaixo pertencem a cada publicação e não representam um total consolidado.</p>'
  return '<div class="case-bruna-identity">'+portrait+participation+'</div><section class="case-chapter" aria-labelledby="content-title"><h2 id="content-title">Conteúdo <em>com identidade.</em></h2><div class="case-content-layout">'+feed+'<div><h3>Planejamento, criação e consistência.</h3><p>A atuação reúne estratégia de conteúdo, gestão das redes sociais, coordenação da equipe de design e automação com ManyChat. As reuniões de alinhamento conectam essas frentes à comunicação da profissional.</p><p>A produção textual é realizada pela cliente.</p><dl class="case-revenue"><div><dt>Curtidas</dt><dd>3,4 mil</dd></div><div><dt>Compartilhamentos</dt><dd>758</dd></div><div><dt>Salvamentos</dt><dd>1 mil</dd></div></dl><small>Indicadores de uma publicação específica no Instagram.</small></div></div></section>'+bruna_result+'<div class="case-bruna-proofs">'+proofs+'</div></section>'
 return participation+result+'<div class="evidence-gallery">'+c['gallery']()+'</div></section>'

def video_footer(commercial,wa):
 html=re.search(r'<section class="closing[\s\S]*?</section>',commercial)[0]
 html=re.sub(r'(?<=["\'])assets/','/assets/',html)
 html=re.sub(r'href="https://wa.me/[^\"]+"',f'href="{wa}"',html)
 html=html.replace(' data-split','').replace('Vamos dar direção<br> <em>ao seu próximo projeto.</em>','Vamos criar<br> <em>o próximo capítulo?</em>')
 html=html.replace('Me conte o momento da sua marca e o que você quer desenvolver. Vamos conversar sobre o caminho que faz sentido para o seu projeto.','Para projetos, parcerias e oportunidades profissionais. Vamos conversar sobre o que podemos construir juntos.')
 for before,after in [('#servicos','/portfolio/#estrategias'),('#projetos','/portfolio/#cases'),('#sobre','/portfolio/#sobre'),('#duvidas','/#duvidas')]:html=html.replace(f'href="{before}"',f'href="{after}"')
 return html
